for p,h in m['artifacts'].items():assert sha(ROOT/p)==h,p
original_manifest=ROOT/'.git/automation_proofs'/(R.name+'_before_csv_repair_manifest.json');original_manifest.write_bytes((R/'data_manifest.json').read_bytes());own=set(m['artifacts'])|{rel(R/'data_manifest.json')}|set(m['shared_files']);staged=set(subprocess.check_output(['git','diff','--cached','--name-only','-z'],cwd=ROOT).decode().strip('\0').split('\0'));assert staged==own
cmd=['git','restore','--staged','--',rel(R),*sorted(m['shared_files'])];start=now();z=subprocess.run(cmd,cwd=ROOT,text=True,capture_output=True);receipts=[{'command':cmd,'cwd':str(ROOT),'started_utc':start,'finished_utc':now(),'exit_code':z.returncode,'stdout':z.stdout,'stderr':z.stderr}];assert z.returncode==0
failed=proof['commands'][-1];full=json.dumps(failed,ensure_ascii=False,indent=2).encode();(R/'publication_preflight_failure_output.json.gz').write_bytes(gzip.compress(full,mtime=0));put(R/'publication_preflight_failed_commands.json',[{**{k:v for k,v in failed.items() if k not in ['stdout','stderr']},'stdout_sha256':__import__('hashlib').sha256(failed['stdout'].encode()).hexdigest(),'stderr':failed['stderr'],'full_stdout_receipt_gzip':rel(R/'publication_preflight_failure_output.json.gz')}])
rows=[]
for p in sorted(R.glob('*.csv')):
 raw=p.read_bytes();before=sha(p);assert b'\r\n' in raw;old=list(csv.DictReader(io.StringIO(raw.decode(),newline='')));newraw=raw.replace(b'\r\n',b'\n');assert b'\r' not in newraw;new=list(csv.DictReader(io.StringIO(newraw.decode(),newline='')));assert old==new;p.write_bytes(newraw);rows.append({'path':rel(p),'before_sha256':before,'after_sha256':sha(p),'old_CRLF_line_count':raw.count(b'\r\n'),'rows':len(old),'all_fields_exactly_equal':True})
assert len(rows)==5
cmd=[sys.executable,str(R/'commands.py'),'exports_retry1'];start=now();z=subprocess.run(cmd,cwd=ROOT,capture_output=True,text=True,env={**os.environ,'PYTHONDONTWRITEBYTECODE':'1','OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1'});receipts.append({'command':cmd,'cwd':str(ROOT),'started_utc':start,'finished_utc':now(),'exit_code':z.returncode,'stdout':z.stdout,'stderr':z.stderr});print(z.stdout+z.stderr,flush=True);assert z.returncode==0
put(R/'publication_repair_commands.json',receipts);put(R/'csv_line_ending_repair.json',{'passed':True,'actual_failed_git_check_exit':2,'failed_publisher_tool_session':60214,'failed_publisher_completion_chunk':'2d8a83','failed_publisher_process_exit':1,'before_repair_manifest_sha256':before_manifest,'change':'Only five CSV CRLF line endings converted to LF;every field/string preserved','CSV_files':rows,'financial_report_sha256':sha(R/'report.json'),'financial_report_unchanged':sha(R/'report.json')==m['finished_report_sha256'],'financial_recalculations':0,'registry_or_account_changes':0,'all_original_code_bindings_preserved':all(sha(ROOT/p)==h for p,h in json.loads((R/'code_binding_before_evaluation.json').read_text())['source_sha256'].items())})
fact={'phase':'publication_precommit_git_diff_check','actual_exit_code':2,'publisher_exit_code':1,'cause':'csv.DictWriter default CRLF interpreted as trailing whitespace','repair':'Convert only five CSV line endings to LF;every field exact equality,export check retryactualexit0','financial_recalculations':0,'full_original_failure_receipt':rel(R/'publication_preflight_failure_output.json.gz')};facts=json.loads((R/'read_failures.json').read_text());facts['facts'].append(fact);put(R/'read_failures.json',facts)
